#!/usr/bin/env node

'use strict';

const { spawnSync } = require('node:child_process');
const { createHash } = require('node:crypto');
const {
  cpSync,
  lstatSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  renameSync,
  rmSync,
  writeFileSync
} = require('node:fs');
const { homedir, tmpdir } = require('node:os');
const path = require('node:path');
const { gunzipSync } = require('node:zlib');

const PAYLOAD_SHA256 = 'a858c6e8e2334b36bb09537f123797fd4c81f8a7c4cc90c57121bc1d113782a0';
const PAYLOAD = '';
const ALLOWED_FILES = new Set(["delegation-planner/SKILL.md","delegation-selector/package-lock.json","delegation-selector/package.json","delegation-selector/public/selector.html","delegation-selector/selection.mjs","delegation-selector/server.mjs","delegation-selector/test-ui.mjs","delegation-selector/test.mjs","hooks/delegation-hooks.json"]);

function fail(message) {
  throw new Error(message);
}

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}

function getStat(target) {
  return lstatSync(target, { throwIfNoEntry: false });
}

function pathExists(target) {
  return getStat(target) !== undefined;
}

function commandWorks(command) {
  const result = spawnSync(command, ['--version'], { stdio: 'ignore' });
  return !result.error && result.status === 0;
}

function run(command, args, options = {}) {
  const result = spawnSync(command, args, {
    cwd: options.cwd,
    env: process.env,
    encoding: 'utf8',
    stdio: options.capture ? ['ignore', 'pipe', 'pipe'] : 'inherit'
  });
  if (result.error) fail(`Could not run ${command}: ${result.error.message}`);
  if (result.status !== 0 && !options.allowFailure) {
    const detail = options.capture ? (result.stderr || result.stdout || '').trim() : '';
    fail(`${command} ${args.join(' ')} failed${detail ? `: ${detail}` : ''}`);
  }
  return result;
}

function assertNodeVersion() {
  const major = Number(process.versions.node.split('.')[0]);
  if (major < 22) fail(`Node.js 22 or newer is required; found ${process.version}.`);
}

function assertPlainPath(target, expected) {
  const stat = getStat(target);
  if (!stat) return;
  if (stat.isSymbolicLink()) fail(`Refusing to use symbolic link: ${target}`);
  if (expected === 'directory' && !stat.isDirectory()) fail(`Expected a directory: ${target}`);
  if (expected === 'file' && !stat.isFile()) fail(`Expected a file: ${target}`);
}

function assertSafeDescendant(base, target) {
  const relative = path.relative(base, target);
  if (relative.startsWith('..') || path.isAbsolute(relative)) fail(`Unsafe installation path: ${target}`);
  let current = base;
  assertPlainPath(current, 'directory');
  for (const segment of relative.split(path.sep).filter(Boolean)) {
    current = path.join(current, segment);
    if (getStat(current)?.isSymbolicLink()) {
      fail(`Refusing to use symbolic link: ${current}`);
    }
  }
}

function readHooks(hooksFile) {
  if (!pathExists(hooksFile)) return {};
  let value;
  try {
    value = JSON.parse(readFileSync(hooksFile, 'utf8'));
  } catch (error) {
    fail(`Cannot install because ${hooksFile} is not valid JSON: ${error.message}`);
  }
  if (!value || Array.isArray(value) || typeof value !== 'object') fail(`${hooksFile} must contain a JSON object.`);
  if (value.hooks !== undefined && (!value.hooks || Array.isArray(value.hooks) || typeof value.hooks !== 'object')) {
    fail(`${hooksFile} has an invalid hooks value.`);
  }
  if (value.hooks?.UserPromptSubmit !== undefined && !Array.isArray(value.hooks.UserPromptSubmit)) {
    fail(`${hooksFile} has an invalid UserPromptSubmit value.`);
  }
  return value;
}

function plannerPathFromCommand(command, userHome) {
  if (typeof command !== 'string') return null;
  const match = command.trim().match(/^(?:\/[^\s]+\/)?cat\s+(?:'([^']+)'|"([^"]+)"|(\S+))\s*$/);
  if (!match) return null;
  let value = match[1] || match[2] || match[3];
  const quoted = match[1] !== undefined || match[2] !== undefined;
  if (quoted && !path.isAbsolute(value)) return null;
  if (!quoted && value === '~') value = userHome;
  else if (!quoted && value.startsWith('~/')) value = path.join(userHome, value.slice(2));
  else if (!path.isAbsolute(value)) return null;
  return path.resolve(value);
}

function mergeHook(config, skillFile, userHome) {
  const result = structuredClone(config);
  result.hooks ||= {};
  result.hooks.UserPromptSubmit ||= [];
  const quotedSkill = `'${skillFile.replaceAll("'", "'\"'\"'")}'`;
  const expectedCommand = `cat ${quotedSkill}`;
  const alreadyInstalled = result.hooks.UserPromptSubmit.some(group =>
    Array.isArray(group?.hooks) && group.hooks.some(hook =>
      hook?.type === 'command' &&
      (hook.command?.trim() === expectedCommand || plannerPathFromCommand(hook.command, userHome) === skillFile)
    )
  );
  if (alreadyInstalled) return { changed: false, value: result };
  result.hooks.UserPromptSubmit.push({
    hooks: [{
      type: 'command',
      command: `cat ${quotedSkill}`,
      timeout: 5,
      statusMessage: 'Loading delegation assessment'
    }]
  });
  return { changed: true, value: result };
}

function unpackPayload(stage) {
  const compressed = Buffer.from(PAYLOAD, 'base64');
  if (sha256(compressed) !== PAYLOAD_SHA256) fail('Installer payload integrity check failed. Download the installer again.');
  const records = JSON.parse(gunzipSync(compressed).toString('utf8'));
  if (!Array.isArray(records) || records.length !== ALLOWED_FILES.size) fail('Installer payload manifest is invalid.');
  const seen = new Set();
  for (const record of records) {
    if (!record || typeof record.path !== 'string' || typeof record.data !== 'string' || typeof record.sha256 !== 'string') {
      fail('Installer payload contains an invalid file record.');
    }
    if (!ALLOWED_FILES.has(record.path) || seen.has(record.path) || path.posix.isAbsolute(record.path) || record.path.includes('\\')) {
      fail(`Installer payload contains an unsafe path: ${record.path}`);
    }
    const segments = record.path.split('/');
    if (segments.some(segment => !segment || segment === '.' || segment === '..')) fail(`Installer payload contains an unsafe path: ${record.path}`);
    const contents = Buffer.from(record.data, 'base64');
    if (sha256(contents) !== record.sha256) fail(`Installer payload integrity check failed for ${record.path}.`);
    const destination = path.join(stage, ...segments);
    mkdirSync(path.dirname(destination), { recursive: true });
    writeFileSync(destination, contents, { flag: 'wx', mode: 0o644 });
    seen.add(record.path);
  }
  if (seen.size !== ALLOWED_FILES.size) fail('Installer payload is incomplete.');
}

function writeAtomic(file, contents) {
  mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.orchestrator-${process.pid}-${Date.now()}`;
  writeFileSync(temporary, contents, { flag: 'wx', mode: 0o600 });
  renameSync(temporary, file);
}

function replaceDirectory(source, destination) {
  mkdirSync(path.dirname(destination), { recursive: true });
  const incoming = `${destination}.orchestrator-${process.pid}-${Date.now()}`;
  cpSync(source, incoming, { recursive: true, errorOnExist: true });
  rmSync(destination, { recursive: true, force: true });
  renameSync(incoming, destination);
}

function createBackup(codexHome, items) {
  const existing = items.filter(item => pathExists(item.source));
  if (existing.length === 0) return null;
  const parent = path.join(codexHome, 'backups', 'orchestrator');
  mkdirSync(parent, { recursive: true });
  const stamp = new Date().toISOString().replaceAll(':', '-').replaceAll('.', '-');
  const backup = mkdtempSync(path.join(parent, `${stamp}-`));
  const manifest = [];
  for (const item of existing) {
    const destination = path.join(backup, item.name);
    mkdirSync(path.dirname(destination), { recursive: true });
    cpSync(item.source, destination, { recursive: lstatSync(item.source).isDirectory() });
    manifest.push({ name: item.name, original: item.source });
  }
  writeFileSync(path.join(backup, 'manifest.json'), `${JSON.stringify({ createdAt: new Date().toISOString(), files: manifest }, null, 2)}\n`);
  return backup;
}

function restoreFile(source, destination, existed) {
  rmSync(destination, { recursive: true, force: true });
  if (existed) {
    mkdirSync(path.dirname(destination), { recursive: true });
    cpSync(source, destination, { recursive: lstatSync(source).isDirectory() });
  }
}

function getMcpState() {
  const result = run('codex', ['mcp', 'get', 'delegation-selector', '--json'], { capture: true, allowFailure: true });
  if (result.status !== 0) return null;
  try {
    return JSON.parse(result.stdout);
  } catch (error) {
    fail(`Codex returned invalid MCP configuration: ${error.message}`);
  }
}

function mcpMatches(value, node, server) {
  if (value?.enabled === false || value?.transport?.type !== 'stdio' ||
    typeof value.transport.command !== 'string' || !path.isAbsolute(value.transport.command) ||
    !Array.isArray(value.transport.args) || value.transport.args.length !== 2 ||
    path.resolve(value.transport.args[0]) !== server || value.transport.args[1] !== '--stdio') return false;
  try {
    // Preserve an equivalent registration: CLI rewrites may discard unrelated settings.
    return realpathSync(value.transport.command) === realpathSync(node);
  } catch (error) {
    if (error.code === 'ENOENT' || error.code === 'ENOTDIR') return false;
    throw error;
  }
}

function install() {
  assertNodeVersion();
  if (!commandWorks('npm')) fail('npm is required and was not found on PATH. Install Node.js 22+ with npm, then try again.');
  if (!commandWorks('codex')) fail('The Codex CLI is required and was not found on PATH. Install Codex, then try again.');

  const userHome = homedir();
  const codexHome = path.resolve(process.env.CODEX_HOME || path.join(userHome, '.codex'));
  const agentsHome = path.join(userHome, '.agents');
  const runtime = path.join(codexHome, 'tools', 'delegation-selector');
  const skillFile = path.join(agentsHome, 'skills', 'delegation-planner', 'SKILL.md');
  const hooksFile = path.join(codexHome, 'hooks.json');
  const configFile = path.join(codexHome, 'config.toml');
  const server = path.join(runtime, 'server.mjs');
  const node = path.resolve(process.execPath);

  assertPlainPath(codexHome, 'directory');
  assertPlainPath(agentsHome, 'directory');
  for (const target of [runtime, hooksFile, configFile]) assertSafeDescendant(codexHome, target);
  assertSafeDescendant(codexHome, path.join(codexHome, 'backups', 'orchestrator'));
  assertSafeDescendant(agentsHome, skillFile);
  assertPlainPath(runtime, 'directory');
  assertPlainPath(skillFile, 'file');
  assertPlainPath(hooksFile, 'file');
  assertPlainPath(configFile, 'file');

  const hooks = readHooks(hooksFile);
  const hookUpdate = mergeHook(hooks, skillFile, userHome);
  const currentMcp = getMcpState();
  const changeMcp = !mcpMatches(currentMcp, node, server);
  const stage = mkdtempSync(path.join(tmpdir(), 'orchestrator-install-'));
  let backup = null;
  let changed = false;
  const previous = {
    runtime: pathExists(runtime),
    skill: pathExists(skillFile),
    hooks: pathExists(hooksFile),
    config: pathExists(configFile)
  };

  try {
    unpackPayload(stage);
    run('npm', ['ci', '--omit=dev', '--ignore-scripts'], { cwd: path.join(stage, 'delegation-selector') });

    const backupItems = [
      { source: runtime, name: 'delegation-selector' },
      { source: skillFile, name: 'delegation-planner/SKILL.md' }
    ];
    if (hookUpdate.changed) backupItems.push({ source: hooksFile, name: 'hooks.json' });
    if (changeMcp) backupItems.push({ source: configFile, name: 'config.toml' });
    backup = createBackup(codexHome, backupItems);

    changed = true;
    replaceDirectory(path.join(stage, 'delegation-selector'), runtime);
    writeAtomic(skillFile, readFileSync(path.join(stage, 'delegation-planner', 'SKILL.md')));
    if (hookUpdate.changed) writeAtomic(hooksFile, `${JSON.stringify(hookUpdate.value, null, 2)}\n`);

    if (changeMcp) {
      if (currentMcp) run('codex', ['mcp', 'remove', 'delegation-selector']);
      run('codex', ['mcp', 'add', 'delegation-selector', '--', node, server, '--stdio']);
    }
  } catch (error) {
    if (changed) {
      try {
        restoreFile(backup && path.join(backup, 'delegation-selector'), runtime, previous.runtime);
        restoreFile(backup && path.join(backup, 'delegation-planner', 'SKILL.md'), skillFile, previous.skill);
        if (hookUpdate.changed) restoreFile(backup && path.join(backup, 'hooks.json'), hooksFile, previous.hooks);
        if (changeMcp) restoreFile(backup && path.join(backup, 'config.toml'), configFile, previous.config);
      } catch (rollbackError) {
        fail(`${error.message}; rollback also failed: ${rollbackError.message}`);
      }
    }
    throw error;
  } finally {
    rmSync(stage, { recursive: true, force: true });
  }

  console.log('\nOrchestrator installed successfully.');
  console.log(`Selector runtime: ${runtime}`);
  console.log(`Planner skill: ${skillFile}`);
  if (backup) console.log(`Backup: ${backup}`);
  console.log('\nFinal required step: open /hooks in Codex, review and trust the Orchestrator hook, then restart Codex and start a new chat.');
}

try {
  install();
} catch (error) {
  console.error(`\nInstallation failed: ${error.message}`);
  process.exitCode = 1;
}
